import re
from collections import Counter

def top_words(text, n=3):
    words = re.findall(r"[a-z0-9']+", text.lower())
    return Counter(words).most_common(n)

def invert(d):
    out = {}
    for k, v in d.items():
        out.setdefault(v, []).append(k)
    return out

def merge_sum(*dicts):
    out = {}
    for d in dicts:
        for k, v in d.items():
            out[k] = out.get(k, 0) + v
    return out

def get_deep(d, path, default=None):
    cur = d
    for key in path:
        if not isinstance(cur, dict) or key not in cur:
            return default
        cur = cur[key]
    return cur

from collections import defaultdict

def merge_stock(a, b):
    total = defaultdict(int)
    for source in (a, b):
        for sku, qty in source.items():
            total[sku] += qty
    return {sku: qty for sku, qty in total.items() if qty > 0}

from collections import defaultdict

def group_by(records, field):
    groups = defaultdict(list)
    for r in records:
        groups[r.get(field)].append(r)
    return dict(groups)

from collections import OrderedDict

class LRU:
    def __init__(self, cap=128):
        self.cap, self.d = cap, OrderedDict()
    def get(self, k, default=None):
        if k not in self.d: return default
        self.d.move_to_end(k)
        return self.d[k]
    def put(self, k, v):
        self.d[k] = v
        self.d.move_to_end(k)
        while len(self.d) > self.cap:
            self.d.popitem(last=False)
